/* Standalone React app (in-browser Babel) for the Lumen & Loom dark home page. */
const { useState, useEffect, useRef, useMemo, useCallback } = React;

/* ----------------------------- Icons ------------------------------- */
const Icon = ({ name, size = 20, ...rest }) => {
  const common = {
    width: size,
    height: size,
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: "currentColor",
    strokeWidth: 1.8,
    strokeLinecap: "round",
    strokeLinejoin: "round",
    "aria-hidden": "true",
    focusable: "false",
    ...rest,
  };
  switch (name) {
    case "search":
      return (<svg {...common}><circle cx="11" cy="11" r="7" /><path d="m20 20-3.5-3.5" /></svg>);
    case "user":
      return (<svg {...common}><circle cx="12" cy="8" r="4" /><path d="M4 21c1.5-4 5-6 8-6s6.5 2 8 6" /></svg>);
    case "bag":
      return (<svg {...common}><path d="M5 8h14l-1.2 11.2A2 2 0 0 1 15.8 21H8.2a2 2 0 0 1-2-1.8L5 8Z" /><path d="M9 8V6a3 3 0 0 1 6 0v2" /></svg>);
    case "heart":
      return (<svg {...common}><path d="M12 20s-7-4.5-7-10a4 4 0 0 1 7-2.6A4 4 0 0 1 19 10c0 5.5-7 10-7 10Z" /></svg>);
    case "menu":
      return (<svg {...common}><path d="M4 7h16M4 12h16M4 17h16" /></svg>);
    case "close":
      return (<svg {...common}><path d="M6 6l12 12M18 6 6 18" /></svg>);
    case "spark":
      return (<svg {...common}><path d="M12 3v4M12 17v4M3 12h4M17 12h4M6 6l2.5 2.5M15.5 15.5 18 18M18 6l-2.5 2.5M8.5 15.5 6 18" /></svg>);
    case "truck":
      return (<svg {...common}><path d="M3 7h11v9H3zM14 11h4l3 3v2h-7" /><circle cx="7" cy="18" r="2" /><circle cx="17" cy="18" r="2" /></svg>);
    case "shield":
      return (<svg {...common}><path d="M12 3 5 6v6c0 4 3 7 7 9 4-2 7-5 7-9V6l-7-3Z" /><path d="m9 12 2 2 4-4" /></svg>);
    case "leaf":
      return (<svg {...common}><path d="M5 19c0-8 6-14 14-14 0 8-6 14-14 14Z" /><path d="M5 19 14 10" /></svg>);
    case "instagram":
      return (<svg {...common}><rect x="3" y="3" width="18" height="18" rx="4" /><circle cx="12" cy="12" r="4" /><circle cx="17.5" cy="6.5" r="0.6" fill="currentColor" stroke="none" /></svg>);
    case "twitter":
      return (<svg {...common}><path d="M4 4l7 9-7 7h3l5.5-5.5L17 20h3l-7.5-9.5L19 4h-3l-4.5 4.5L8 4H4Z" /></svg>);
    case "youtube":
      return (<svg {...common}><rect x="3" y="6" width="18" height="12" rx="3" /><path d="m11 10 4 2-4 2v-4Z" fill="currentColor" stroke="none" /></svg>);
    case "pinterest":
      return (<svg {...common}><circle cx="12" cy="12" r="9" /><path d="M11 7c2.5-.5 5 1 5 4 0 2.5-1.8 4-3.7 4-1 0-1.7-.5-2-1l-.6 2.4c-.2.8-.7 1.7-1 2.4" /></svg>);
    default:
      return null;
  }
};

/* --------------------------- Product art --------------------------- */
/* Inline SVG illustrations as decorative product imagery, themed dark. */
const ProductArt = ({ seed = 0, label }) => {
  const palettes = [
    ["#2d1f17", "#7a4a2b", "#d68a52"],
    ["#1a1f2b", "#33486e", "#7cc4ff"],
    ["#221422", "#5e2a52", "#d062a9"],
    ["#13211b", "#2a5a44", "#7fd1a5"],
    ["#231a10", "#7a5a23", "#f0c060"],
    ["#1a1a22", "#3a3a55", "#a8a8d0"],
    ["#221015", "#7a2333", "#ff6680"],
    ["#10221f", "#1f5a55", "#5fd5c0"],
  ];
  const [c1, c2, c3] = palettes[seed % palettes.length];
  const variant = seed % 4;
  return (
    <svg viewBox="0 0 400 400" preserveAspectRatio="xMidYMid slice" role="img" aria-label={label}>
      <defs>
        <linearGradient id={`bg${seed}`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor={c1} />
          <stop offset="100%" stopColor="#0b0d10" />
        </linearGradient>
        <radialGradient id={`spot${seed}`} cx="0.7" cy="0.3" r="0.6">
          <stop offset="0%" stopColor={c3} stopOpacity="0.35" />
          <stop offset="100%" stopColor={c3} stopOpacity="0" />
        </radialGradient>
      </defs>
      <rect width="400" height="400" fill={`url(#bg${seed})`} />
      <rect width="400" height="400" fill={`url(#spot${seed})`} />
      {variant === 0 && (
        <g>
          <rect x="120" y="110" width="160" height="200" rx="14" fill={c2} />
          <rect x="135" y="125" width="130" height="120" rx="6" fill={c1} opacity="0.7" />
          <circle cx="200" cy="280" r="14" fill={c3} />
        </g>
      )}
      {variant === 1 && (
        <g>
          <circle cx="200" cy="200" r="100" fill={c2} />
          <circle cx="200" cy="200" r="64" fill={c1} />
          <circle cx="200" cy="200" r="28" fill={c3} />
        </g>
      )}
      {variant === 2 && (
        <g>
          <path d="M120 280 Q200 80 280 280 Z" fill={c2} />
          <path d="M150 280 Q200 150 250 280 Z" fill={c3} opacity="0.7" />
        </g>
      )}
      {variant === 3 && (
        <g>
          <rect x="100" y="160" width="200" height="120" rx="60" fill={c2} />
          <rect x="140" y="180" width="120" height="80" rx="40" fill={c1} />
          <circle cx="200" cy="220" r="20" fill={c3} />
        </g>
      )}
    </svg>
  );
};

const HeroArt = () => (
