        <stop offset="60%" stopColor="#ff5a36" stopOpacity="0.05" />
        <stop offset="100%" stopColor="#000" stopOpacity="0" />
      </radialGradient>
    </defs>
    <rect width="600" height="750" fill="url(#heroBg)" />
    <rect width="600" height="750" fill="url(#heroLight)" />
    <ellipse cx="300" cy="640" rx="240" ry="30" fill="#000" opacity="0.5" />
    <rect x="180" y="300" width="240" height="320" rx="18" fill="#3a2519" />
    <rect x="200" y="320" width="200" height="280" rx="10" fill="#5a3a25" />
    <circle cx="300" cy="430" r="70" fill="#1a0f0c" />
    <circle cx="300" cy="430" r="48" fill="#d68a52" />
    <rect x="230" y="540" width="140" height="60" rx="8" fill="#1a0f0c" opacity="0.7" />
    <circle cx="120" cy="180" r="50" fill="#7a4a2b" opacity="0.6" />
    <circle cx="490" cy="160" r="34" fill="#ff5a36" opacity="0.4" />
    <path d="M60 700 Q300 660 540 700" stroke="#76808c" strokeWidth="1" fill="none" opacity="0.4" />
  </svg>
);

const ArticleArt = ({ seed = 0, label }) => {
  const themes = [
