  --text: #f1f3f5;
  --text-muted: #a4adb8;
  --text-dim: #76808c;
  --accent: #ff5a36;
  --accent-hover: #ff7559;
  --accent-contrast: #0b0d10;
  --success: #4ade80;
  --warn: #fbbf24;
  --focus: #7cc4ff;
  --radius: 12px;
  --radius-sm: 8px;
  --shadow: 0 8px 24px rgba(0, 0, 0, 0.45);
  --maxw: 1280px;
  --gap: 1.25rem;
  --font: "Inter", system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-display: "Fraunces", "Playfair Display", Georgia, serif;
}

* { box-sizing: border-box; }

html { color-scheme: dark; }

body {
  margin: 0;
  font-family: var(--font);
  background: var(--bg);
  color: var(--text);
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img { max-width: 100%; display: block; }

a { color: inherit; text-decoration: none; }

a:hover { text-decoration: underline; text-underline-offset: 3px; }

:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

button { font: inherit; cursor: pointer; }

/* Skip link */
.skip-link {
  position: absolute;
  left: 0;
  top: 0;
  background: var(--accent);
  color: var(--accent-contrast);
  padding: 0.75rem 1rem;
  font-weight: 600;
  transform: translateY(-120%);
  transition: transform 150ms ease;
  z-index: 1000;
}
.skip-link:focus { transform: translateY(0); }

.container {
  max-width: var(--maxw);
  margin: 0 auto;
  padding: 0 1.25rem;
}

/* ---------- Top promo ---------- */
.promo-bar {
  background: linear-gradient(90deg, #1a0f0c, #2a1410 50%, #1a0f0c);
  border-bottom: 1px solid var(--border);
  font-size: 0.85rem;
  color: var(--text-muted);
}
.promo-bar__inner {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 0.5rem;
  padding: 0.5rem 1.25rem;
  text-align: center;
}
.promo-bar strong { color: var(--text); }

/* ---------- Header ---------- */
.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  background: rgba(11, 13, 16, 0.92);
  backdrop-filter: saturate(140%) blur(10px);
  -webkit-backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--border);
}
.header-row {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1.5rem;
  padding: 0.9rem 0;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 0.6rem;
  font-family: var(--font-display);
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}
.brand__mark {
  width: 32px; height: 32px;
  border-radius: 50%;
  background: radial-gradient(circle at 30% 30%, var(--accent), #b53219);
  display: inline-block;
}

.primary-nav ul {
  list-style: none;
  display: flex;
  gap: 1.5rem;
  margin: 0;
  padding: 0;
  justify-content: center;
}
.primary-nav a {
  color: var(--text-muted);
  font-size: 0.95rem;
  font-weight: 500;
  padding: 0.4rem 0.2rem;
  border-bottom: 2px solid transparent;
}
.primary-nav a:hover { color: var(--text); text-decoration: none; }
.primary-nav a[aria-current="page"] {
  color: var(--text);
  border-bottom-color: var(--accent);
}

.header-actions {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}
.icon-btn {
  background: transparent;
  border: 1px solid transparent;
  color: var(--text-muted);
  width: 40px; height: 40px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--radius-sm);
  position: relative;
}
.icon-btn:hover { color: var(--text); background: var(--bg-elev); border-color: var(--border); }
.icon-btn .badge {
  position: absolute;
  top: 4px; right: 4px;
  background: var(--accent);
  color: var(--accent-contrast);
  font-size: 0.7rem;
  font-weight: 700;
  min-width: 18px;
  height: 18px;
  border-radius: 9px;
  padding: 0 5px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* ---------- Hero ---------- */
.hero {
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(80% 60% at 80% 20%, rgba(255, 90, 54, 0.18), transparent 60%),
    radial-gradient(60% 60% at 10% 90%, rgba(124, 196, 255, 0.10), transparent 60%),
    linear-gradient(180deg, #0e1116, #0b0d10);
  border-bottom: 1px solid var(--border);
}
.hero__grid {
  display: grid;
  grid-template-columns: 1.05fr 1fr;
  gap: 3rem;
  align-items: center;
  padding: 4.5rem 0 5rem;
}
.hero__eyebrow {
  display: inline-block;
  font-size: 0.8rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 600;
  margin-bottom: 1rem;
}
.hero__title {
  font-family: var(--font-display);
  font-size: clamp(2.4rem, 5vw, 4rem);
  line-height: 1.05;
  margin: 0 0 1.25rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.hero__title em {
  font-style: italic;
  color: var(--accent);
  font-weight: 500;
}
.hero__lede {
  font-size: 1.1rem;
  color: var(--text-muted);
  max-width: 52ch;
  margin: 0 0 2rem;
}
.hero__cta { display: flex; gap: 0.75rem; flex-wrap: wrap; }

.btn {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.85rem 1.4rem;
  border-radius: 999px;
  font-weight: 600;
  font-size: 0.95rem;
  border: 1px solid transparent;
  transition: background 150ms ease, color 150ms ease, border-color 150ms ease, transform 150ms ease;
}
.btn:hover { text-decoration: none; }
.btn--primary { background: var(--accent); color: var(--accent-contrast); }
.btn--primary:hover { background: var(--accent-hover); }
.btn--ghost { background: transparent; color: var(--text); border-color: var(--border-strong); }
.btn--ghost:hover { background: var(--bg-elev); border-color: var(--text-muted); }

.hero__media {
  position: relative;
  aspect-ratio: 4 / 5;
  border-radius: 20px;
  overflow: hidden;
  background: linear-gradient(135deg, #1a1f26, #2a1812);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
}
.hero__media svg { width: 100%; height: 100%; display: block; }
.hero__tag {
  position: absolute;
  bottom: 1rem; left: 1rem;
  background: rgba(11, 13, 16, 0.85);
  border: 1px solid var(--border-strong);
  padding: 0.5rem 0.85rem;
  border-radius: 999px;
  font-size: 0.85rem;
  color: var(--text);
  display: inline-flex;
  gap: 0.5rem;
  align-items: center;
}
.hero__tag .dot {
  width: 8px; height: 8px;
  background: var(--success);
  border-radius: 50%;
}

.trust-row {
  display: flex;
  flex-wrap: wrap;
  gap: 2rem;
  padding: 1.5rem 0;
  border-top: 1px solid var(--border);
  color: var(--text-muted);
  font-size: 0.9rem;
  justify-content: space-between;
}
.trust-row__item { display: inline-flex; gap: 0.6rem; align-items: center; }
.trust-row__item strong { color: var(--text); font-weight: 600; }

/* ---------- Sections ---------- */
.section {
  padding: 4.5rem 0;
  border-bottom: 1px solid var(--border);
}
.section--tight { padding: 3rem 0; }
.section-header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 1.5rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}
.section-header__text { max-width: 60ch; }
.section-header h2 {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 3vw, 2.4rem);
  margin: 0 0 0.5rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.section-header p { margin: 0; color: var(--text-muted); }
.section-header__link {
  color: var(--text);
  font-weight: 600;
  font-size: 0.9rem;
  border-bottom: 1px solid var(--border-strong);
  padding-bottom: 2px;
}
.section-header__link:hover { color: var(--accent); border-bottom-color: var(--accent); text-decoration: none; }

/* Category chips */
.chips {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}
.chip {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  color: var(--text-muted);
  padding: 0.5rem 1rem;
  border-radius: 999px;
  font-size: 0.85rem;
  font-weight: 500;
}
.chip:hover, .chip[aria-pressed="true"] {
  color: var(--text);
  border-color: var(--accent);
  background: rgba(255, 90, 54, 0.1);
}
.chip[aria-pressed="true"] { color: var(--accent); }

/* Product grid */
.product-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: var(--gap);
}
.product {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color 150ms ease, transform 150ms ease;
  position: relative;
}
.product:hover, .product:focus-within {
  border-color: var(--border-strong);
  transform: translateY(-2px);
}
.product__media {
  position: relative;
  aspect-ratio: 1 / 1;
  background: var(--bg-elev-2);
  overflow: hidden;
}
.product__media svg { width: 100%; height: 100%; display: block; }
.product__badge {
  position: absolute;
  top: 0.75rem; left: 0.75rem;
  background: var(--bg);
  color: var(--text);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  padding: 0.3rem 0.6rem;
  border-radius: 6px;
  border: 1px solid var(--border-strong);
}
.product__badge--new { color: var(--success); border-color: rgba(74, 222, 128, 0.4); }
.product__badge--sale { color: var(--accent); border-color: rgba(255, 90, 54, 0.5); }
.product__wishlist {
  position: absolute;
  z-index: 2;
  top: 0.5rem; right: 0.5rem;
  width: 36px; height: 36px;
  border-radius: 50%;
  background: rgba(11, 13, 16, 0.7);
  color: var(--text-muted);
  border: 1px solid var(--border);
  display: inline-flex;
  align-items: center;
  justify-content: center;
}
.product__wishlist:hover, .product__wishlist[aria-pressed="true"] { color: var(--accent); border-color: var(--accent); }
.product__body {
  padding: 1rem 1rem 1.1rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  flex: 1;
}
.product__category {
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-dim);
}
.product__title {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
  line-height: 1.3;
}
.product__title a {
  color: var(--text);
}
.product__title a::after {
  content: "";
  position: absolute;
  inset: 0;
}
.product__title a:hover { text-decoration: none; color: var(--text); }
.product__rating {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--text-muted);
  font-size: 0.8rem;
}
.stars { color: var(--warn); letter-spacing: 1px; font-size: 0.85rem; }
.product__price-row {
  display: flex;
  align-items: baseline;
  gap: 0.5rem;
  margin-top: auto;
  padding-top: 0.4rem;
}
.price { font-size: 1.05rem; font-weight: 700; color: var(--text); }
.price--strike { color: var(--text-dim); text-decoration: line-through; font-weight: 500; font-size: 0.9rem; }
.price-discount { color: var(--accent); font-size: 0.8rem; font-weight: 700; }

/* Deals */
.deals-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: var(--gap);
}
.deal {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.75rem;
  position: relative;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  min-height: 240px;
  transition: border-color 150ms ease, transform 150ms ease;
}
.deal:hover { border-color: var(--border-strong); transform: translateY(-2px); }
.deal__eyebrow {
  font-size: 0.75rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--accent);
  font-weight: 600;
  margin-bottom: 0.5rem;
}
.deal__title {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 600;
  margin: 0 0 0.5rem;
  line-height: 1.15;
}
.deal__desc { color: var(--text-muted); margin: 0 0 1rem; font-size: 0.95rem; }
.deal__link {
  color: var(--text);
  font-weight: 600;
  font-size: 0.9rem;
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
}
.deal__link::after { content: "→"; transition: transform 150ms ease; }
.deal:hover .deal__link::after { transform: translateX(4px); }

.deal--feature {
  grid-row: span 2;
  background:
    radial-gradient(60% 60% at 80% 20%, rgba(255, 90, 54, 0.25), transparent 70%),
    linear-gradient(135deg, #1f1410, #0f1216);
  border-color: rgba(255, 90, 54, 0.3);
  min-height: 500px;
  padding: 2.5rem;
}
.deal--feature .deal__title {
  font-size: clamp(2rem, 3.2vw, 2.8rem);
  max-width: 14ch;
}
.deal--feature .deal__countdown {
  display: flex;
  gap: 0.75rem;
  margin: 1.25rem 0 1.5rem;
}
.countdown-unit {
  background: rgba(11, 13, 16, 0.6);
  border: 1px solid var(--border-strong);
  border-radius: 8px;
  padding: 0.6rem 0.85rem;
  text-align: center;
  min-width: 64px;
}
.countdown-unit__value {
  font-family: var(--font-display);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text);
  display: block;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.countdown-unit__label {
  font-size: 0.7rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-dim);
  margin-top: 0.3rem;
  display: block;
}

.deal--accent {
  background: linear-gradient(135deg, #1a2230, #0f1216);
  border-color: rgba(124, 196, 255, 0.25);
}
.deal--accent .deal__eyebrow { color: var(--focus); }

/* Editorial */
.editorial-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--gap);
}
.article {
  background: var(--bg-elev);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color 150ms ease, transform 150ms ease;
  position: relative;
}
.article:hover { border-color: var(--border-strong); transform: translateY(-2px); }
.article__media {
  aspect-ratio: 16 / 10;
  overflow: hidden;
  background: var(--bg-elev-2);
}
.article__media svg { width: 100%; height: 100%; display: block; }
.article__body { padding: 1.5rem; display: flex; flex-direction: column; gap: 0.6rem; flex: 1; }
.article__meta {
  font-size: 0.75rem;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-dim);
  display: flex;
  gap: 0.6rem;
  align-items: center;
}
.article__meta .dot-sep { width: 3px; height: 3px; background: var(--text-dim); border-radius: 50%; display: inline-block; }
.article__title {
  font-family: var(--font-display);
  font-size: 1.3rem;
  margin: 0;
  line-height: 1.25;
  font-weight: 600;
}
.article__title a { color: var(--text); }
.article__title a::after { content: ""; position: absolute; inset: 0; }
.article__title a:hover { text-decoration: none; }
.article__excerpt { color: var(--text-muted); margin: 0; font-size: 0.95rem; }
.article__read {
  margin-top: auto;
  padding-top: 0.4rem;
  font-size: 0.85rem;
  color: var(--text-muted);
  font-weight: 500;
}

/* Newsletter */
.newsletter {
  background:
    radial-gradient(60% 80% at 20% 50%, rgba(255, 90, 54, 0.15), transparent 70%),
    linear-gradient(135deg, #14181d, #0e1115);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 3rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
}
.newsletter h2 {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 2.6vw, 2.2rem);
  margin: 0 0 0.6rem;
  font-weight: 600;
}
.newsletter p { margin: 0; color: var(--text-muted); }
.newsletter form { display: flex; gap: 0.5rem; }
.newsletter label {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
.newsletter input[type="email"] {
  flex: 1;
  background: var(--bg);
  border: 1px solid var(--border-strong);
  color: var(--text);
  padding: 0.85rem 1.1rem;
  border-radius: 999px;
  font-size: 0.95rem;
  font-family: inherit;
  min-width: 0;
}
.newsletter input[type="email"]::placeholder { color: var(--text-dim); }
.newsletter input[type="email"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
.newsletter__status {
  margin-top: 0.75rem;
  font-size: 0.85rem;
  color: var(--success);
  min-height: 1.2em;
}
.newsletter__status--error { color: #ff8a8a; }

/* Footer */
.site-footer {
  background: #08090b;
  border-top: 1px solid var(--border);
  padding: 4rem 0 2rem;
  color: var(--text-muted);
  font-size: 0.9rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(4, 1fr);
  gap: 2rem;
  margin-bottom: 3rem;
}
.footer-grid h3 {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text);
  margin: 0 0 1rem;
  font-weight: 600;
}
.footer-grid ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 0.5rem; }
.footer-grid a:hover { color: var(--text); }
.footer-brand p { max-width: 32ch; margin: 0.75rem 0 1rem; }
.socials { display: flex; gap: 0.5rem; }
.socials .icon-btn { width: 36px; height: 36px; }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 1.5rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem;
  font-size: 0.8rem;
  color: var(--text-dim);
}
.footer-bottom ul { list-style: none; display: flex; gap: 1.25rem; padding: 0; margin: 0; }

/* ---------- Responsive ---------- */
@media (max-width: 960px) {
  .hero__grid { grid-template-columns: 1fr; gap: 2rem; padding: 3rem 0; }
  .hero__media { max-width: 480px; margin: 0 auto; width: 100%; }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal--feature { grid-row: auto; grid-column: span 2; min-height: 320px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .newsletter { grid-template-columns: 1fr; padding: 2rem; }
}

@media (max-width: 720px) {
  .header-row { grid-template-columns: auto 1fr auto; }
  .menu-toggle {
    display: inline-flex;
    background: transparent;
    border: 1px solid var(--border);
    color: var(--text);
    width: 40px; height: 40px;
    border-radius: var(--radius-sm);
    align-items: center;
    justify-content: center;
    margin-right: 0.25rem;
  }
  .primary-nav {
    display: none;
    position: absolute;
    top: 100%; left: 0; right: 0;
    background: var(--bg-elev);
    border-bottom: 1px solid var(--border);
    padding: 0.75rem 1.25rem;
  }
  .primary-nav[data-open="true"] { display: block; }
  .primary-nav ul { flex-direction: column; gap: 0.25rem; align-items: stretch; }
  .primary-nav a { padding: 0.65rem 0.4rem; border-bottom: 1px solid var(--border); }
  .primary-nav a[aria-current="page"] { border-bottom-color: var(--accent); }

  .deals-grid, .editorial-grid, .footer-grid { grid-template-columns: 1fr; }
  .deal--feature { grid-column: auto; }
  .newsletter form { flex-direction: column; }
  .newsletter .btn { justify-content: center; }
  .section { padding: 3rem 0; }
}

@media (max-width: 380px) {
  .product-grid { grid-template-columns: 1fr; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    transition-duration: 0.001ms !important;
  }
}

@media (forced-colors: active) {
  .btn, .product, .deal, .article, .chip, .icon-btn, .newsletter input[type="email"] {
    border: 1px solid CanvasText;
  }
  .product__title a::after, .article__title a::after { outline: 1px solid transparent; }
}
