  min-width: 18px;
  height: 18px;
  border-radius: 9px;
  padding: 0 5px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

/* Mobile menu toggle */
.menu-toggle { display: none; }

/* ---------- Hero ---------- */
.hero {
  position: relative;
  overflow: hidden;
  background:
    radial-gradient(80% 60% at 80% 20%, rgba(255, 90, 54, 0.18), transparent 60%),
    radial-gradient(60% 60% at 10% 90%, rgba(124, 196, 255, 0.10), transparent 60%),
