}
.trust-row__item { display: inline-flex; gap: 0.6rem; align-items: center; }
.trust-row__item strong { color: var(--text); font-weight: 600; }

/* ---------- Sections ---------- */
.section {
  padding: 4.5rem 0;
  border-bottom: 1px solid var(--border);
}
.section--tight { padding: 3rem 0; }
.section-header {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 1.5rem;
  margin-bottom: 2rem;
  flex-wrap: wrap;
}
.section-header__text { max-width: 60ch; }
.section-header h2 {
  font-family: var(--font-display);
  font-size: clamp(1.75rem, 3vw, 2.4rem);
  margin: 0 0 0.5rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}
.section-header p { margin: 0; color: var(--text-muted); }
.section-header__link {
  color: var(--text);
  font-weight: 600;
  font-size: 0.9rem;
  border-bottom: 1px solid var(--border-strong);
  padding-bottom: 2px;
}
.section-header__link:hover { color: var(--accent); border-bottom-color: var(--accent); text-decoration: none; }

/* Category chips */
.chips {
  display: flex;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 2rem;
}
.chip {
  background: var(--bg-elev);
  border: 1px solid var(--border);
