  justify-content: center;
}
.product__wishlist:hover, .product__wishlist[aria-pressed="true"] { color: var(--accent); border-color: var(--accent); }
.product__body {
  padding: 1rem 1rem 1.1rem;
  display: flex;
  flex-direction: column;
  gap: 0.4rem;
  flex: 1;
}
.product__category {
  font-size: 0.72rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--text-dim);
}
.product__title {
  font-size: 1rem;
  font-weight: 600;
  margin: 0;
  line-height: 1.3;
}
.product__title a {
  color: var(--text);
}
.product__title a::after {
  content: "";
  position: absolute;
  inset: 0;
}
.product__title a:hover { text-decoration: none; color: var(--text); }
.product__rating {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  color: var(--text-muted);
