/* Newsletter */
.newsletter {
  background:
    radial-gradient(60% 80% at 20% 50%, rgba(255, 90, 54, 0.15), transparent 70%),
    linear-gradient(135deg, #14181d, #0e1115);
  border: 1px solid var(--border);
  border-radius: 20px;
  padding: 3rem;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 2rem;
  align-items: center;
}
.newsletter h2 {
  font-family: var(--font-display);
  font-size: clamp(1.6rem, 2.6vw, 2.2rem);
  margin: 0 0 0.6rem;
  font-weight: 600;
}
.newsletter p { margin: 0; color: var(--text-muted); }
.newsletter form { display: flex; gap: 0.5rem; }
.newsletter label {
  position: absolute;
  width: 1px; height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
  white-space: nowrap;
}
.newsletter input[type="email"] {
  flex: 1;
  background: var(--bg);
  border: 1px solid var(--border-strong);
  color: var(--text);
  padding: 0.85rem 1.1rem;
  border-radius: 999px;
  font-size: 0.95rem;
  font-family: inherit;
  min-width: 0;
}
.newsletter input[type="email"]::placeholder { color: var(--text-dim); }
.newsletter input[type="email"]:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}
.newsletter__status {
  margin-top: 0.75rem;
  font-size: 0.85rem;
  color: var(--success);
  min-height: 1.2em;
}
.newsletter__status--error { color: #ff8a8a; }

/* Footer */
.site-footer {
  background: #08090b;
  border-top: 1px solid var(--border);
  padding: 4rem 0 2rem;
  color: var(--text-muted);
  font-size: 0.9rem;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.4fr repeat(4, 1fr);
  gap: 2rem;
  margin-bottom: 3rem;
}
.footer-grid h3 {
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--text);
  margin: 0 0 1rem;
  font-weight: 600;
}
.footer-grid ul { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 0.5rem; }
.footer-grid a:hover { color: var(--text); }
.footer-brand p { max-width: 32ch; margin: 0.75rem 0 1rem; }
.socials { display: flex; gap: 0.5rem; }
.socials .icon-btn { width: 36px; height: 36px; }
.footer-bottom {
  border-top: 1px solid var(--border);
  padding-top: 1.5rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: 0.75rem;
  font-size: 0.8rem;
  color: var(--text-dim);
}
.footer-bottom ul { list-style: none; display: flex; gap: 1.25rem; padding: 0; margin: 0; }

/* ---------- Responsive ---------- */
@media (max-width: 960px) {
  .hero__grid { grid-template-columns: 1fr; gap: 2rem; padding: 3rem 0; }
  .hero__media { max-width: 480px; margin: 0 auto; width: 100%; }
  .deals-grid { grid-template-columns: 1fr 1fr; }
  .deal--feature { grid-row: auto; grid-column: span 2; min-height: 320px; }
  .editorial-grid { grid-template-columns: 1fr 1fr; }
  .footer-grid { grid-template-columns: 1fr 1fr; }
  .newsletter { grid-template-columns: 1fr; padding: 2rem; }
