const fs = require("fs");
const path = require("path");
const { JSDOM, ResourceLoader } = require("jsdom");

class LocalLoader extends ResourceLoader {
  fetch(url, options) {
    // Allow file:// and CDN. Cache CDN scripts in node_modules-like dir.
    return super.fetch(url, options);
  }
}

(async () => {
  const indexPath = path.resolve(__dirname, "index.html");
  const html = fs.readFileSync(indexPath, "utf8");

  const dom = new JSDOM(html, {
    url: "file://" + indexPath,
    runScripts: "dangerously",
    resources: new LocalLoader({ strictSSL: false }),
    pretendToBeVisual: true,
  });

  // Wait for scripts and React to mount
  await new Promise((resolve, reject) => {
    const start = Date.now();
    const tick = () => {
      const main = dom.window.document.querySelector("main h1");
      if (main) return resolve();
      if (Date.now() - start > 30000) return reject(new Error("React did not render in time"));
      setTimeout(tick, 200);
    };
    dom.window.addEventListener("load", () => setTimeout(tick, 500));
  });

  // Inject axe-core into the jsdom window
  const axeSource = fs.readFileSync(require.resolve("axe-core/axe.min.js"), "utf8");
  const scriptEl = dom.window.document.createElement("script");
  scriptEl.textContent = axeSource;
  dom.window.document.head.appendChild(scriptEl);

  const results = await dom.window.eval(`
    axe.run(document, {
      runOnly: { type: 'tag', values: ['wcag2a','wcag2aa','wcag21a','wcag21aa','wcag22aa','best-practice'] },
      resultTypes: ['violations','incomplete']
    })
  `);

  const summarize = (arr) =>
    arr.map((v) => ({
      id: v.id,
      impact: v.impact,
