/* --------------------------- Product art --------------------------- */
/* Inline SVG illustrations as decorative product imagery, themed dark. */
const ProductArt = ({ seed = 0, label }) => {
  const palettes = [
    ["#2d1f17", "#7a4a2b", "#d68a52"],
    ["#1a1f2b", "#33486e", "#7cc4ff"],
    ["#221422", "#5e2a52", "#d062a9"],
    ["#13211b", "#2a5a44", "#7fd1a5"],
    ["#231a10", "#7a5a23", "#f0c060"],
    ["#1a1a22", "#3a3a55", "#a8a8d0"],
    ["#221015", "#7a2333", "#ff6680"],
    ["#10221f", "#1f5a55", "#5fd5c0"],
  ];
  const [c1, c2, c3] = palettes[seed % palettes.length];
  const variant = seed % 4;
  return (
    <svg viewBox="0 0 400 400" preserveAspectRatio="xMidYMid slice" role="img" aria-label={label}>
      <defs>
        <linearGradient id={`bg${seed}`} x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor={c1} />
          <stop offset="100%" stopColor="#0b0d10" />
        </linearGradient>
        <radialGradient id={`spot${seed}`} cx="0.7" cy="0.3" r="0.6">
          <stop offset="0%" stopColor={c3} stopOpacity="0.35" />
          <stop offset="100%" stopColor={c3} stopOpacity="0" />
        </radialGradient>
      </defs>
      <rect width="400" height="400" fill={`url(#bg${seed})`} />
      <rect width="400" height="400" fill={`url(#spot${seed})`} />
      {variant === 0 && (
        <g>
          <rect x="120" y="110" width="160" height="200" rx="14" fill={c2} />
          <rect x="135" y="125" width="130" height="120" rx="6" fill={c1} opacity="0.7" />
          <circle cx="200" cy="280" r="14" fill={c3} />
        </g>
      )}
      {variant === 1 && (
        <g>
          <circle cx="200" cy="200" r="100" fill={c2} />
          <circle cx="200" cy="200" r="64" fill={c1} />
          <circle cx="200" cy="200" r="28" fill={c3} />
        </g>
      )}
      {variant === 2 && (
        <g>
          <path d="M120 280 Q200 80 280 280 Z" fill={c2} />
          <path d="M150 280 Q200 150 250 280 Z" fill={c3} opacity="0.7" />
        </g>
      )}
      {variant === 3 && (
        <g>
          <rect x="100" y="160" width="200" height="120" rx="60" fill={c2} />
          <rect x="140" y="180" width="120" height="80" rx="40" fill={c1} />
          <circle cx="200" cy="220" r="20" fill={c3} />
        </g>
      )}
    </svg>
  );
};

