  const [cartCount, setCartCount] = useState(2);
  const [announcement, setAnnouncement] = useState("");

  const toggleWish = useCallback((id) => {
    setWished(prev => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
        setAnnouncement("Removed from wishlist.");
      } else {
        next.add(id);
        setAnnouncement("Added to wishlist.");
      }
      return next;
    });
  }, []);

  const onShop = useCallback(() => setCartCount(c => c), []);

  return (
    <>
      <a className="skip-link" href="#main">Skip to main content</a>
      <PromoBar />
      <Header
        cartCount={cartCount}
        onMenu={() => setMenuOpen(o => !o)}
        menuOpen={menuOpen}
      />
      <main id="main">
        <Hero onShop={onShop} />
        <FeaturedSection wished={wished} onWish={toggleWish} onAdd={() => setCartCount(c => c + 1)} />
        <DealsSection />
        <EditorialSection />
        <Newsletter />
      </main>
      <Footer />
      <div className="visually-hidden" role="status" aria-live="polite">{announcement}</div>
